package org.example.wikimapreader.car;
import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;
import org.robolectric.RobolectricTestRunner;import org.robolectric.annotation.Config;import androidx.test.core.app.ApplicationProvider;
import org.json.*;import java.nio.file.*;import java.util.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class ContractsTest {
 @Test public void fixtureGeometryMatchesJs()throws Exception{JSONObject raw=new JSONObject(Files.readString(Paths.get(System.getProperty("wikireader.fixtures"),"box-moscow.projection.json")));List<Place> places=Place.area(raw);assertFalse(places.isEmpty());Place first=places.get(0);assertEquals(6120946,first.id);assertEquals(55.738564,first.coords[0][0],1e-6);assertEquals(37.585859,first.coords[0][1],1e-6);}
 @Test public void rejectsErrorInHttp200()throws Exception{assertThrows(Exception.class,()->WikiApi.validate(new JSONObject("{\"error\":\"quota reached\"}"),"box",0));assertThrows(Exception.class,()->WikiApi.validate(new JSONObject("{\"folder\":{}}"),"box",0));assertThrows(Exception.class,()->WikiApi.validate(new JSONObject("{\"id\":56,\"title\":\"Wrong\"}"),"place.getbyid",55));}
 @Test public void requestBoundsAndSearch()throws Exception{assertThrows(Exception.class,()->WikiApi.build("box","K",new JSONObject("{\"bbox\":[0,0,1,1]}")));assertThrows(Exception.class,()->WikiApi.build("box","",new JSONObject()));assertTrue(WikiApi.build("search","K",new JSONObject("{\"query\":\"Москва\",\"lat\":55,\"lon\":37}")).contains("count=20"));}
 @Test public void migrationDedupNamespaceAndDelete()throws Exception{CarStore s=CarStore.get(ApplicationProvider.getApplicationContext());JSONObject p=new JSONObject("{\"id\":99991,\"source\":\"wikimapia\",\"title\":\"A\"}");JSONArray legacy=new JSONArray().put(p).put(p).put(new JSONObject("{\"id\":99991,\"source\":\"demo\",\"title\":\"D\"}"));s.sync(legacy,new JSONArray(),true);assertEquals(2,s.favorites().length());s.sync(legacy,new JSONArray().put(new JSONObject().put("place",p).put("remove",true)),true);assertEquals(1,s.favorites().length());s.sync(legacy,new JSONArray(),true);assertEquals(1,s.favorites().length());}
 @Test public void invalidGeometryFiltered()throws Exception{Place p=Place.from(new JSONObject("{\"id\":3,\"polygon\":[[37,55],[null,5],[181,10],[\"\",0]]}"));assertEquals(1,p.coords.length);}
 @Test public void cacheStoresNoDescriptions()throws Exception{CarStore s=CarStore.get(ApplicationProvider.getApplicationContext());JSONObject r=new JSONObject("{\"bbox\":[37,55,37.01,55.01],\"updated\":1,\"state\":{\"places\":[{\"id\":42,\"title\":\"X\",\"coords\":[[55,37]],\"description\":\"SECRET\"}],\"complete\":true}} ");s.putArea(r);assertFalse(s.areas().toString().contains("SECRET"));assertTrue(s.areas().length()>0);}
}
